<script setup>
import ListPager from './ListPager.vue';
import AuditList from './AuditList.vue';
import PagedRecords from './PagedRecords.vue';
import TargetsPanel from './TargetsPanel.vue';
import RegistrationFilters from './RegistrationFilters.vue';
import ReportStamp from './ReportStamp.vue';
import InsightPanel from './InsightPanel.vue';
// Native-style mobile composition adapted from MDS DashboardPageMobile/ListPageMobile.
import {ref} from 'vue';import {s,title,canAdmin,canEdit,isSuper,nav,run,navigate,selectEvent,showEventList,reports,number,dateText,roleNames,callLabel,utmContent,exportExcel,exportPng,insights,loadRows,editRow,setRole,saveEvent} from './store';
import MMobileTopBar from './mobile/MMobileTopBar.vue';import MMobileBottomNav from './mobile/MMobileBottomNav.vue';import ReportFilters from './ReportFilters.vue';import ChartPanel from './ChartPanel.vue';import KpiCard from './KpiCard.vue';import SettingsFields from './SettingsFields.vue';import ImportFields from './ImportFields.vue';import MemberImport from './MemberImport.vue';
const more=ref(false),filters=ref(false);const items=[{key:'tong-quan',label:'Tổng quan',icon:'home'},{key:'du-lieu',label:'Dữ liệu',icon:'list'},{key:'nguon-du-lieu',label:'Nhập liệu',icon:'upload'},{key:'thanh-vien',label:'Thành viên',icon:'users'},{key:'more',label:'Thêm',icon:'menu-2'}];
function go(key){if(key==='more'){more.value=true;return;}more.value=false;run(()=>navigate(key));}
function back(){if(more.value){more.value=false;return;}if(s.route!=='tong-quan'){go('tong-quan');return;}run(()=>showEventList());}
</script><template><div class="mds-mobile-app relative flex h-full flex-col overflow-hidden"><MMobileTopBar :title="more?'Thêm':title" back-label="Quay lại" show-more @back="back" @more="more=!more"/><main class="scroll-region page-body stack"><div v-if="s.error" role="alert" class="error">{{s.error}}</div><div v-if="s.message" role="status" class="notice">{{s.message}}</div><progress v-if="s.busy" aria-label="Đang xử lý"/>
<template v-if="more"><section class="card stack"><h2>{{s.user.name}}</h2><p class="muted">{{s.user.email}}</p><MButton variant="secondary" @click="run(()=>showEventList())">Chọn sự kiện</MButton><MButton variant="primary" v-if="isSuper" @click="s.dialog='new-event'">Tạo sự kiện</MButton><MButton variant="secondary" @click="more=false;run(()=>navigate('muc-tieu'))">Thiết lập sự kiện</MButton><MButton v-if="canAdmin" variant="secondary" @click="more=false;run(()=>navigate('nhat-ky'))">Nhật ký</MButton><MButton variant="secondary" @click="s.appearance=true">Giao diện</MButton><MButton variant="secondary" @click="s.dialog='account'">Tài khoản & mật khẩu</MButton></section></template>
<template v-else><label class="field">Sự kiện<MCombobox :model-value="s.event?.id" :options="s.events.map(e=>({value:e.id,label:e.name}))" @update:model-value="run(()=>selectEvent($event))"/></label><MEmptyState v-if="!s.event" type="initial" title="Chọn sự kiện để bắt đầu"/>
<template v-else-if="s.route==='tong-quan'"><div class="row"><MButton v-if="isSuper" variant="secondary" @click="s.dialog='new-event'">Tạo sự kiện</MButton><MButton variant="secondary" :disabled="s.reportBusy||!s.report" :loading="s.busy" @click="run(exportExcel)">Xuất Excel</MButton><MButton variant="secondary" :disabled="s.reportBusy||!s.report" :loading="s.busy" @click="run(exportPng)">Xuất ảnh</MButton></div><ReportFilters/><MTabs :model-value="s.reportTab" :tabs="[{key:'chart',label:'Dashboard'},{key:'table',label:'Bảng số liệu'},{key:'targets',label:'Chi tiết mục tiêu'}]" @update:model-value="s.reportTab=$event;s.table=$event==='table'"/><MCombobox v-if="s.reportTab!=='targets'" v-model="s.selected" multiple :options="reports" placeholder="Chọn báo cáo"/><MCheckbox v-if="s.reportTab!=='targets'" v-model="s.showPercent" label="Hiển thị % trên biểu đồ"/><div v-if="s.reportBusy" role="status" class="row card"><MSpinner/>Đang cập nhật số liệu…</div><div v-else-if="s.report" data-report class="stack"><ReportStamp/><div v-if="!s.report.snapshot.id" class="notice">Chưa có dữ liệu để tổng hợp. Chọn Nhập dữ liệu để bắt đầu.</div><div v-else-if="!s.report.current.total" class="notice">Không có đăng ký phù hợp bộ lọc. Chọn “Xem toàn bộ mới nhất” để trở về tổng hợp.</div><TargetsPanel v-if="s.reportTab==='targets'" mobile /><template v-else><div class="kpi-grid"><KpiCard v-for="kind in ['total','completion','clevel','ratio','call_rate',...(s.event.mode==='hybrid'?['online','offline']:[])]" :key="kind" :kind="kind"/></div><p v-if="s.event.mode==='hybrid'&&s.report.current.modes.find(m=>m.value==='unknown')?.count" class="notice">{{number(s.report.current.modes.find(m=>m.value==='unknown').count)}} đăng ký chưa có hình thức tham dự, chưa tính vào Online hoặc Offline.</p><p v-if="s.event.mode==='hybrid'&&s.report.current.modes.find(m=>m.value==='both')?.count" class="muted">Khách chọn cả hai được tính vào Online và Offline; tổng hai ô có thể lớn hơn tổng đăng ký.</p><ChartPanel v-if="s.selected.includes('positions')" mobile title="Cơ cấu chức vụ" :rows="s.report.current.positions" :table="s.table" pie/><ChartPanel v-if="s.selected.includes('sizes')" mobile title="Quy mô doanh nghiệp" :rows="s.report.current.sizes" :table="s.table"/><ChartPanel v-if="s.selected.includes('trend')" mobile trend title="Xu hướng đăng ký" :rows="s.report.current.trend.map(r=>({...r,label:dateText(r.label),percent:s.report.current.total?r.count/s.report.current.total*100:0}))" :table="s.table"/><template v-if="s.selected.includes('sources')"><label class="field">Chiều nguồn khách<MCombobox v-model="s.dimension" :options="s.report.sourceDimensions.map(d=>({value:d.name,label:d.name}))"/></label><ChartPanel mobile source :title="s.dimension||'Nguồn khách'" :rows="s.report.current.sourceBreakdowns.find(d=>d.name===s.dimension)?.values||[]" :table="s.table"/></template><InsightPanel/></template></div></template>
<template v-else-if="s.route==='thanh-vien'"><MemberImport/><PagedRecords :key="s.event.id" :rows="s.members" v-slot="{rows:pageRows}"><section class="card mobile-list"><article v-for="m in pageRows" :key="m.id"><h3>{{m.name}}</h3><p>{{m.email}}</p><div class="row mt-3"><MSelect v-if="isSuper" :model-value="m.role" :options="[{value:'editor',label:'Editor'},{value:'admin',label:'Admin'}]" @update:model-value="run(()=>setRole(m,$event))"/><span v-else>{{roleNames[m.role]}}</span><MButton v-if="isSuper||(canAdmin&&m.role==='editor')" variant="link" @click="s.editMember=m;s.dialog='remove-member'">Thu hồi quyền</MButton></div></article><MEmptyState v-if="!s.members.length" type="initial" title="Chưa cấp quyền chỉnh sửa"/></section></PagedRecords></template>
<template v-else-if="s.route==='du-lieu'"><RegistrationFilters/><section class="card mobile-list"><article v-for="r in s.rows" :key="r.id"><h3>{{r.name||'Chưa có tên'}}</h3><dl><dt>Số điện thoại</dt><dd>{{r.phone||'—'}}</dd><template v-if="s.rowHasTaxId"><dt>Mã số thuế</dt><dd>{{r.tax_id||'—'}}</dd></template><dt>Công ty</dt><dd>{{r.company||'—'}}</dd><dt>Chức vụ</dt><dd>{{r.position||'—'}}</dd><dt>Ngày submit</dt><dd>{{dateText(r.submitted_at)}}</dd><dt>utm_content</dt><dd>{{utmContent(r)||'—'}}</dd><dt>Gọi xác nhận</dt><dd>{{callLabel(r.call_status)}}</dd></dl><MButton v-if="canEdit" variant="secondary" @click="editRow(r)">Chỉnh sửa</MButton></article><MEmptyState v-if="!s.rows.length" type="no-result" title="Không có đăng ký phù hợp"/></section><ListPager :page="s.page" :page-size="s.pageSize" :total="s.rowTotal" :loading="s.rowsBusy" @update:page-size="s.pageSize=$event" @update:page="s.page=$event;run(loadRows)"/></template>
<ImportFields v-else-if="s.route==='nguon-du-lieu'"/><SettingsFields v-else-if="s.route==='muc-tieu'"/><template v-else-if="s.route==='nhat-ky'"><AuditList v-if="canAdmin" :event-id="s.event.id"/><p v-else>Bạn không có quyền xem nhật ký.</p></template></template></main>
<footer v-if="!more&&s.route==='muc-tieu'&&canEdit" class="sticky-actions"><MButton variant="secondary" @click="run(()=>selectEvent(s.event.id))">Hủy</MButton><MButton variant="primary" :loading="s.busy" @click="run(saveEvent)">Lưu</MButton></footer><MMobileBottomNav :items="items" :active="more?'more':s.route" @select="go"/></div></template>
